PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, login TEXT UNIQUE NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('teacher','student')), password TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS classes(id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id), name TEXT NOT NULL, timezone TEXT NOT NULL, invite TEXT UNIQUE NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS members(class_id TEXT REFERENCES classes(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(class_id,user_id));
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, title TEXT NOT NULL, course TEXT NOT NULL, unit TEXT NOT NULL, target INTEGER NOT NULL, due INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE, title TEXT NOT NULL, goal INTEGER NOT NULL, starts INTEGER NOT NULL, ends INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, assignment_id TEXT NOT NULL REFERENCES assignments(id) ON DELETE CASCADE, word TEXT NOT NULL, label TEXT NOT NULL, correct INTEGER NOT NULL CHECK(correct IN (0,1)), duration INTEGER NOT NULL CHECK(duration BETWEEN 0 AND 120000), mode TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_assignment_user_time ON attempts(assignment_id,user_id,created);
CREATE INDEX IF NOT EXISTS assignments_class ON assignments(class_id);
CREATE INDEX IF NOT EXISTS members_user ON members(user_id);
